// A five-step memory trial. Its attempt lock is saved before opening the dialog.
window.createLearningUI=function(api,complete){
 'use strict';const F=window.Frontera,$=id=>document.getElementById(id),arrows=['↑','→','↓','←'];let trial=null,timer=null,result=false;
 function finish(out){if(!trial)return;clearTimeout(timer);timer=null;result=true;api.save();api.refresh();$('trialSequence').textContent=out.passed?'✦ Técnica aprendida':'Prueba terminada';$('trialMessage').textContent=out.passed?'¡Aprobaste! Se gastó 1 punto. '+(out.equipped?'La técnica ocupa el siguiente espacio libre.':'Ya tienes cuatro técnicas. Elige cuál reemplazar desde Ataques.'):'No se gastaron puntos. '+(trial.level===100?'Al nivel 100 ya no hay un próximo nivel para reintentar.':'Podrás reintentar este movimiento en el nivel '+(trial.level+1)+'.');$('trialTimer').textContent='';$('trialProgress').textContent=out.passed?'5 / 5':'Sin aprobar';document.querySelectorAll('[data-trial-input]').forEach(b=>b.disabled=true);$('trialClose').textContent='Volver a habilidades';$('trialClose').focus({preventScroll:true});complete(out);}
 function tick(){if(!trial||result)return;const now=Date.now(),out=F.expireLearnTrial(api.state(),now);if(out.done){finish(out);return}const preview=now<trial.previewUntil;$('trialSequence').textContent=preview?trial.sequence.map(n=>arrows[n]).join('   '):'●   ●   ●   ●   ●';$('trialMessage').textContent=preview?'Memoriza la secuencia. Después repítela en orden.':'Repite la secuencia con las flechas o con los botones.';$('trialTimer').textContent=preview?'Memorizar · '+Math.ceil((trial.previewUntil-now)/1000)+' s':'Tiempo · '+Math.max(0,Math.ceil((trial.deadline-now)/1000))+' s';document.querySelectorAll('[data-trial-input]').forEach(b=>b.disabled=preview);timer=setTimeout(tick,100);}
 function input(value){if(!trial||result)return;const out=F.learnTrialInput(api.state(),value);if(out.done)finish(out);else if(!out.preview)$('trialProgress').textContent=out.position+' / 5';}
 function open(index,key){if(api.battle())return false;const out=F.beginLearnTrial(api.state(),index,key);if(!out.ok){api.toast(out.reason);return false}trial=out;result=false;api.save();$('trialTitle').textContent='Aprender '+F.MOVE_DATA[key].name;$('trialProgress').textContent='0 / 5';$('trialClose').textContent='Abandonar la prueba';api.openDialog('learningDialog');tick();return true;}
 function close(){if(trial&&!result)finish(F.cancelLearnTrial(api.state()));$('learningDialog').close();trial=null;api.openDialog('skillsDialog');}
 $('trialClose').onclick=close;$('learningDialog').addEventListener('cancel',e=>{e.preventDefault();close()});$('learningDialog').addEventListener('close',()=>{if(trial&&!result)finish(F.cancelLearnTrial(api.state()));clearTimeout(timer);trial=null;});
 for(const b of document.querySelectorAll('[data-trial-input]'))b.onclick=()=>input(Number(b.dataset.trialInput));
 window.addEventListener('keydown',e=>{if(!$('learningDialog').open||result||e.repeat)return;const value={ArrowUp:0,ArrowRight:1,ArrowDown:2,ArrowLeft:3,w:0,d:1,s:2,a:3}[e.key];if(value!==undefined){e.preventDefault();input(value)}});
 return{open,input,tick};
};
